22	func acquireSharedLock(dir string) (*fileLock, error) {
23		path := dir + "/lock"
24		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
25		if err != nil {
26			return nil, err
27		}
28		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
29			f.Close()
30			return nil, err
31		}
32		return &fileLock{f: f}, nil
33	}
34	
35	// loadAndVerifyLocked 读取记录文件，校验其记录格式版本、内容校验和（校验和
36	// 已包含父记录关系）、父记录是否存在，以及世界数据是否自洽。
37	//
38	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
39	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
40	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
41	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
42	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
43	// CorruptError，绝不报成 VersionRejectedError。
44	//
45	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
46	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
47	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
48	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
49		env, err := loadRecord(recordPath(a.dir, id))
50		if err != nil {
51			if errors.Is(err, os.ErrNotExist) {
52				return nil, &NotFoundError{Record: id}
53			}
54			return nil, &CorruptError{Record: id, Reason: err.Error()}
55		}
56		if env.ID != id {
57			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
58		}
59		if env.Format != recordFormatVersion {
60			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
61		}
62		if got := computeChecksum(env); got != env.Checksum {
63			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
64		}
65		// 父记录关系必须落到一个真实存在的记录上。
66		if env.Parent != "" {
67			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
68				if errors.Is(err, os.ErrNotExist) {
69					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
70				}
71				return nil, err
72			}
73		}
74		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
75		// 其余状态合法，也按损坏处理，不自动把时间改成零。
76		if env.State.Time < 0 {
77			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
78		}
79		if err := validateInitialData(InitialData{
80			Seed:       env.State.Seed,
81			Rules:      env.State.Rules,
82			Characters: env.State.Characters,
83		}); err != nil {
84			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
85		}
86		return env, nil
87	}
88	
89	func versionAccepted(version string, accepted []string) bool {
90		for _, v := range accepted {
91			if v == version {
92				return true
93			}
94		}
95		return false
96	}
97	
98	func envToRecord(env *envelope) Record {
99		return Record{
100			ID:        env.ID,
101			Parent:    env.Parent,
102			SlotFirst: env.SlotFirst,
103			State:     cloneState(env.State),
104		}
105	}
106	
107	// Latest 读取槽当前最新记录。
108	//
109	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
110	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（格式版本不受支持、
111	// 校验和不符、父记录缺失、无法解析、时间片为负）时返回 *CorruptError。
112	// 格式与版本分别判断：格式不受支持的记录一律报损坏，不报版本拒绝。
113	// 读取不会改写存档。
114	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
115		if !validSlotName(slot) {
116			return Record{}, &NotFoundError{Slot: slot}
117		}
118		lock, err := acquireSharedLock(a.dir)
119		if err != nil {
120			return Record{}, err
121		}
122		defer lock.release()
123	
124		id, err := a.readLatestLocked(slot)
125		if err != nil {
126			return Record{}, err
127		}
128		env, err := a.loadAndVerifyLocked(id)
129		if err != nil {
130			if ce, ok := err.(*CorruptError); ok {
131				ce.Slot = slot
132			}
133			return Record{}, err
134		}
135		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
136			return Record{}, &VersionRejectedError{
137				Slot:     slot,
138				Record:   id,
139				Version:  env.State.Rules.Version,
140				Accepted: append([]string(nil), acceptedVersions...),
141			}
142		}
143		return envToRecord(env), nil
144	}
145	
146	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
147	//
148	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
149	// 且记录必须属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
150	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
151		if !validSlotName(slot) {
152			return Record{}, &NotFoundError{Slot: slot}
153		}
154		lock, err := acquireSharedLock(a.dir)
155		if err != nil {
156			return Record{}, err
157		}
158		defer lock.release()
159	
160		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
161			return Record{}, err
162		}
163		env, err := a.loadAndVerifyLocked(id)
164		if err != nil {
165			if ce, ok := err.(*CorruptError); ok {
166				ce.Slot = slot
167			}
168			return Record{}, err
169		}
170		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
171			return Record{}, &VersionRejectedError{
172				Slot:     slot,
173				Record:   id,
174				Version:  env.State.Rules.Version,
175				Accepted: append([]string(nil), acceptedVersions...),
176			}
177		}
178		return envToRecord(env), nil
179	}
180	
181	// History 返回槽的历史记录元信息，按该槽保存生效的次序排列（最新在
182	// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
183	// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间、世界时间
184	// 片或规则版本无关。
185	//
186	// 列出的每条元信息都对应历史中一份确实保存生效、且通过与 Record 一致
187	// 的完整性检查的记录：标识与文件一致、记录格式受支持、内容校验和正确
188	// （含父记录关系）、世界状态合法、直接父记录文件存在。损坏、缺失或无
189	// 法解析的单条记录一律略过，继续返回其余合格记录——最新记录或某条中间
190	// 记录出问题不会让整个列表失败；全部记录都被略过时返回空列表与成功
191	// 结果。完整性检查不包含规则版本取舍：History 没有可接受版本参数，
192	// 完好但规则版本较旧的记录仍正常列出。该方法只做只读遍历，不修补或
193	// 删除记录、不改变槽当前指向、不改写历史与世界规则。槽不存在返回
194	// *NotFoundError，槽指针无法解析返回 *CorruptError。
195	func (a *Archive) History(slot string) ([]RecordInfo, error) {
196		if !validSlotName(slot) {
197			return nil, &NotFoundError{Slot: slot}
198		}
199		lock, err := acquireSharedLock(a.dir)
200		if err != nil {
201			return nil, err
202		}
203		defer lock.release()
204	
205		history, err := a.slotHistoryLocked(slot)
206		if err != nil {
207			return nil, err
208		}
209		infos := make([]RecordInfo, 0, len(history))
210		for _, id := range history {
211			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
212			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
213			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
214			env, verifyErr := a.loadAndVerifyLocked(id)
215			if verifyErr != nil {
216				continue
217			}
218			infos = append(infos, RecordInfo{
219				ID:        env.ID,
220				Parent:    env.Parent,
221				SlotFirst: env.SlotFirst,
222				Version:   env.State.Rules.Version,
223			})
224		}
225		return infos, nil
226	}
227	
228	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
229	// 版本可接受的已保存记录。
230	//
231	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
232	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
233	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
234	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
235	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
236	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
237	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
238	//
239	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
240	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
241	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
242	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
243	// 不会被选中。
244	//
245	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
246	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
247	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
248	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
249	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
250		if !validSlotName(slot) {
251			return Record{}, &NotFoundError{Slot: slot}
252		}
253		lock, err := acquireSharedLock(a.dir)
254		if err != nil {
255			return Record{}, err
256		}
257		defer lock.release()
258	
259		history, err := a.slotHistoryLocked(slot)
260		if err != nil {
261			return Record{}, err
262		}
263	
264		env, err := a.firstRecoverableLocked(history, acceptedVersions)
265		if err != nil {
266			var ue *UnrecoverableError
267			if errors.As(err, &ue) {
268				ue.Slot = slot
269			}
270			return Record{}, err
271		}
272		return envToRecord(env), nil
273	}
274	
275	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
276	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
277	//
278	// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
279	// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
280	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
281	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
282	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
283	// 补全）。
284	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
285		var lastReason string
286		for _, id := range history {
287			env, verifyErr := a.loadAndVerifyLocked(id)
288			if verifyErr != nil {
289				lastReason = verifyErr.Error()
290				continue
291			}
292			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
293				lastReason = (&VersionRejectedError{
294					Record:  id,
295					Version: env.State.Rules.Version,
296				}).Error()
297				continue
298			}
299			return env, nil
300		}
301	
302		if lastReason == "" {
303			lastReason = "槽中没有任何可确认归属的历史记录"
304		}
305		return nil, &UnrecoverableError{Reason: lastReason}
306	}
307

